public final class JpaInvoiceRepository implements InvoiceRepository {
    private final EntityManager em;                       // request/transaction scoped

    @Override public Optional<Invoice> findById(InvoiceId id) {
        return Optional.ofNullable(em.find(Invoice.class, id.value()));
    }
    @Override public List<Invoice> findOverdue(LocalDate on) {
        return em.createQuery("select i from Invoice i where i.due < :on", Invoice.class)
                 .setParameter("on", on).getResultList(); // JPQL stays in infrastructure
    }
    @Override public void add(Invoice invoice) { em.persist(invoice); }  // flush: unit of work
}
